#include <iostream>
#include <string>
#include <memory>

class Document {
public:
    virtual std::string getName() = 0;
    virtual void open() = 0;
    virtual ~Document() = default;
};

class RealDocument : public Document {
private:
    std::string name;
    std::string content;

public:
    RealDocument(const std::string& name) : name(name) {
        std::cout << "Loading: " << name << "..." << std::endl;
        content = "Big content of " + name;
        std::cout << name << " loaded from disk." << std::endl;
    }

    std::string getName() override {
        return name;
    }

    void open() override {
        std::cout << "Opening: " << name << std::endl;
    }
};

class DocumentProxy : public Document {
private:
    std::string name;
    std::unique_ptr<RealDocument> realDoc;

public:
    DocumentProxy(const std::string& name) : name(name) {
        std::cout << "Proxy created for: " << name << ". Not loaded yet." << std::endl;
    }

    std::string getName() override {
        return name;
    }

    void open() override {
        if (!realDoc) {
            std::cout << "Proxy: Loading document for the first time..." << std::endl;
            realDoc = std::make_unique<RealDocument>(name);
        } else {
            std::cout << "Proxy: Using already loaded document." << std::endl;
        }
        realDoc->open();
    }
};

int main() {
    DocumentProxy doc("resume.pdf");
    std::cout << "Document name: " << doc.getName() << std::endl;
    doc.open();
    doc.open();

    return 0;
}

