#include <iostream>
#include <string>
#include <memory>

class Document {
public:
    virtual std::string getName() = 0;
    virtual void open() = 0;
    virtual ~Document() = default;
};

class RealDocument : public Document {
private:
    std::string name;

public:
    RealDocument(const std::string& name) : name(name) {
        std::cout << "Loading: " << name << "..." << std::endl;
    }

    std::string getName() override { return name; }

    void open() override {
        std::cout << "Opening: " << name << std::endl;
    }
};

class DocumentProxy : public Document {
private:
    std::string name;
    std::unique_ptr<RealDocument> realDoc;

public:
    DocumentProxy(const std::string& name) : name(name) {}

    std::string getName() override { return name; }

    void open() override {
        if (!realDoc) {
            realDoc = std::make_unique<RealDocument>(name);
        }
        realDoc->open();
    }
};

class LoggingDocumentProxy : public Document {
private:
    std::shared_ptr<Document> wrappedDoc;

public:
    LoggingDocumentProxy(std::shared_ptr<Document> wrappedDoc) : wrappedDoc(wrappedDoc) {}

    std::string getName() override { return wrappedDoc->getName(); }

    void open() override {
        std::cout << "[LOG] open() called for " << getName() << std::endl;
        wrappedDoc->open();
        std::cout << "[LOG] open() completed for " << getName() << std::endl;
    }
};

int main() {
    std::shared_ptr<Document> inner = std::make_shared<DocumentProxy>("resume.pdf");
    LoggingDocumentProxy doc(inner);
    doc.open();

    return 0;
}

