import java.util.HashMap;
import java.util.Map;

interface ApiService {
    String fetch(String endpoint);
}

class RealApiService implements ApiService {
    @Override
    public String fetch(String endpoint) {
        System.out.println("RealApi: Calling external API: " + endpoint);
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return "Response from [" + endpoint + "]";
    }
}

class CachingApiProxy implements ApiService {
    private RealApiService realService;
    private Map<String, String> cache = new HashMap<>();

    public CachingApiProxy() {
        this.realService = new RealApiService();
    }

    @Override
    public String fetch(String endpoint) {
        if (cache.containsKey(endpoint)) {
            System.out.println("CachingProxy: Cache HIT for: " + endpoint);
            return cache.get(endpoint);
        }
        System.out.println("CachingProxy: Cache MISS for: " + endpoint);
        String result = realService.fetch(endpoint);
        cache.put(endpoint, result);
        return result;
    }

    public void clearCache() {
        System.out.println("CachingProxy: Cache cleared.");
        cache.clear();
    }
}

public class ApiCacheDemo {
    public static void main(String[] args) {
        CachingApiProxy api = new CachingApiProxy();

        System.out.println("--- First request (cache miss) ---");
        System.out.println(api.fetch("/api/users"));

        System.out.println("\n--- Same request again (cache hit) ---");
        System.out.println(api.fetch("/api/users"));

        System.out.println("\n--- Different request (cache miss) ---");
        System.out.println(api.fetch("/api/products?status=active"));

        System.out.println("\n--- Clear cache and retry ---");
        api.clearCache();
        System.out.println(api.fetch("/api/users"));
    }
}

